func writeManifest(t *testing.T, root, directory, content string) {
	t.Helper()
	path := filepath.Join(root, directory, "engine.toml")
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(strings.TrimSpace(content)+"\n"), 0o600); err != nil {
		t.Fatal(err)
	}
}

